function walkTo(dest){if(transit?.aboard){toast('Pehle bus se utro.');return;}navTarget=dest;autoWalk=findPath(sim.player,dest,world.obstacles);if(!autoWalk.length){toast('That point is blocked. Choose a nearby walkway.');return;}toast(`Walking to ${dest.label||'your marker'}. WASD takes over.`,3);}
function lead(id){trackedStory=id;const dest=questDestination(id);if($('#journal').open)$('#journal').close();if(mode==='title')return;mode='play';$('#screen').classList.add('hidden');sound.pause(false);walkTo(dest);}
function renderJournal(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===activeTab));let html='';if(activeTab==='stories'){html=[['Sound check',game.speakerReturned&&game.performance,game.speakerReturned?'Speaker returned. Ravi trusts you.':game.performance?'Performance complete. Return the speaker to Ravi for a proper ending.':game.speakerDelivered?`Speaker connected. Audience ${game.crowd}/3. Talk to people or G to perform; then E by the stage mic.`:game.speakerBorrowed?'Pick up the speaker by the chai cart. Carry it to the stage and press E.':'Speak to Mira by the fountain, then Ravi at the chai cart.'],['Unpaid career counsellor',game.adviceComplete,game.adviceComplete?'Officer Sharma will remember you. So will Kabir’s camera.':game.advice>=2?'Your opening question landed. Return for the follow-up, or leave it there.':'Kabir, in purple by the fountain, has a questionable idea. Officer Sharma is nearby.'],['Wrong group chat',game.buddyComplete,game.buddyComplete?'Nikhil follows you. He would prefer that nobody mentions the bus.':'Find Nikhil’s blue phone by the bench east of the fountain. Bring it to the volunteer in front of the bus.'],['Your own diversions',false,`Water passed: ${game.water}/3 · Photographs: ${game.photos.length}/3 · Chases: ${sim.escaped} · Borrow a cape, perform, try the speaker in different places, or discover what the key changes.`]].map(([t,done,desc])=>`<article class="story"><span>${done?'✓ RESOLVED':'○ IN YOUR OWN TIME'}</span><h3>${t}</h3><p>${desc}</p></article>`).join('');}else if(activeTab==='memories'){html=game.memories.length?game.memories.map(m=>`<article class="story"><span>${Math.floor(m.time/60)}:${String(Math.floor(m.time%60)).padStart(2,'0')} INTO THE AFTERNOON</span><h3>${m.title}</h3><p>${m.text}</p></article>`).join(''):'<p>The group chat is unusually quiet. Go make a story.</p>';}else if(activeTab==='sources'){html='<p>This is an original fictional social sandbox inspired by reported protest humour. July and October reports describe different events. All dialogue, characters, rewards, AI, bus behaviour and release outcomes are invented. The tuition-teacher and cute-uncle premises came from the user and remain unverified. Heat values are fictional game balance, not legal advice or predictions about actual officers.</p>'+sources.map(([title,outlet,url,desc])=>`<article class="story"><h3>${title}</h3><p>${desc}</p><a href="${url}" target="_blank" rel="noopener noreferrer">${outlet} ↗</a></article>`).join('')+'<p>Original Blender environment assets; MakeHuman-derived CC0 human meshes with original skeletal clips; Poly Haven CC0 materials and sky. Three.js: MIT licence. Reference photography provenance is retained with the source project. This is a recognisable interpretation, not a photogrammetric replica.</p><p><b>Recorded music:</b> <a href="https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1400011" target="_blank" rel="noopener noreferrer">Monkeys Spinning Monkeys</a> and <a href="https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1400024" target="_blank" rel="noopener noreferrer">Run Amok</a> by Kevin MacLeod (incompetech.com). Existing 2014 recordings, licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">Creative Commons Attribution 4.0</a>. Original downloaded files are unchanged; game playback may loop, excerpt, adjust volume and crossfade them. No composer endorsement is implied. <a href="assets/audio/PUBLISHED-MUSIC-CREDITS.txt" target="_blank">Full recording credits</a>.</p>';}else html='<p><b>Move:</b> WASD or arrows. Drag the mouse to rotate the camera; mouse wheel zooms. Shift runs and drains stamina. Space jumps over low obstacles.</p><p><b>Act:</b> E interacts with the nearest person or object. Q puts down what you carry. G performs for people nearby. F takes a photo. 1–5 choose dialogue options. H chants when ten recruited people are nearby; talk to people to invite them. J opens this journal; Escape pauses.</p><p><b>Objects persist:</b> dropped objects remain where you left them. The minimap shows them. Carrying the speaker slows you; place it down to play music. A water crate lets you offer cups to people.</p><p><b>Reactions:</b> group chants and taking the key raise attention; a fresh friendly joke adds aura and rizz without heat. Repetition wears thin. Officers visibly notice before pursuing. People remember help and repeated antics. Being caught keeps story progress and starts a brief fictional aftermath.</p><p><b>Your ending:</b> resolve stories in any order, then visit the green Metro sign. The living day runs for twenty minutes of active play, from morning to evening. P opens its map, encounters and inspector; V joins a nearby scene. Menus pause time. The final recap reflects what you actually did.</p><p><b>Touch:</b> left stick moves; drag the view to look; buttons on the right act. Desktop keyboard and mouse give the best control.</p>';if(activeTab==='stories'&&journalPrior!=='title')html='<div class="lead-buttons"><button data-lead="mira">Walk to Mira</button><button data-lead="sound">Follow sound check</button><button data-lead="advice">Follow career advice</button><button data-lead="buddy">Follow missing friend</button><button data-lead="water">Water run</button><button data-lead="crowd">Find a crowd</button><button data-lead="costume">Costume rail</button><button data-lead="key">Bus key</button><button data-lead="metro">Walk to Metro</button></div>'+html;if(activeTab==='memories'){const summary=campaignSummary(game,sim);html='<div class="badges">'+summary.badges.map(b=>`<span class="${b.done?'earned':''}">${b.done?'✓':'○'} ${b.title}</span>`).join('')+'</div>'+html;}$('#journalContent').innerHTML=html;document.querySelectorAll('[data-lead]').forEach(b=>b.onclick=()=>lead(b.dataset.lead));}
function updateNPCs(dt){updateLivingActors(dt);navigationCredits=Math.min(3,navigationCredits+dt*30);let pathBudget=Math.floor(navigationCredits);const escortId=day?.state.crisisTasks?.task?.actorId;const priority=new Set([escortId,...(storyProjection?.reservedActorIds||[]),...npcs.filter(n=>n.sceneTarget).map(n=>n.id)]);const ordered=[...npcs.filter(n=>priority.has(n.id)),...npcs.filter(n=>!priority.has(n.id))];for(let n of ordered){n.model.visible=!n.hidden;if(n.hidden)continue;n.pose=Math.max(0,n.pose-dt);n.streetGestureTime=Math.max(0,(n.streetGestureTime||0)-dt);let dest=null;const d=dist(sim.player,n);if(n.sceneTarget){dest=n.sceneTarget;n.dayTarget=n.sceneTarget;}else if(n.dayTarget&&!n.follow){dest=n.dayTarget;}else if(n.follow){const index=n.id==='kabir'?1:2;if(d>2+index*.6)dest={x:sim.player.x-Math.sin(sim.player.yaw)*2+index*.8,z:sim.player.z-Math.cos(sim.player.yaw)*2};}else if(n.recruited&&game.rally){const i=npcs.indexOf(n);dest={x:game.rally.x+(i%6-2.5)*1.2,z:game.rally.z+2+Math.floor(i/6)*1.3};if(game.performance)n.pose=.1;}else if(n.ambient&&!talk){const loud=items.find(i=>i.type==='speaker'&&i.on&&!i.held&&dist(i,n)<14);if(loud&&!game.speakerDelivered){dest={x:loud.x+Math.cos(n.phase)*3,z:loud.z+Math.sin(n.phase)*3};n.pose=.1;}else if(d<1.3){dest={x:n.x+(n.x-sim.player.x)*2,z:n.z+(n.z-sim.player.z)*2};}else dest={x:n.home.x+Math.sin(sim.time*.1+n.phase)*2,z:n.home.z+Math.cos(sim.time*.12+n.phase)*2};}
if(n.incidentOrder&&!n.sceneTarget&&!n.follow){n.dayTarget=n.incidentOrder.to;dest=n.dayTarget;n.intentGesture=n.incidentOrder.gesture;const facing=n.incidentOrder.facePoint||npcs.find(q=>q.id===n.incidentOrder.faceId)||(n.incidentOrder.faceId==='player'?sim.player:null);if(facing&&dist(n,dest)<.3)n.yaw=Math.atan2(facing.x-n.x,facing.z-n.z);}if(!n.sceneTarget&&(n.shop||n.streetGestureTime>0&&!n.incidentOrder))dest=null;if(n.busYieldTarget&&sim.time<n.busYieldUntil){dest=dist(n,n.busYieldTarget)>.18?n.busYieldTarget:null;}else n.busYieldTarget=null;if(n.incidentOrder?.speed===0&&!n.sceneTarget&&!n.busYieldTarget)dest=null;if(talk?.npc===n&&!n.busYieldTarget){dest=null;n.yaw=Math.atan2(sim.player.x-n.x,sim.player.z-n.z);}if(dest){const ox=n.x,oz=n.z;let aim=dest;if(n.dayTarget&&!n.busYieldTarget){if(dist(n,dest)>.8&&pathBudget>0&&sim.time>=(n.nextPathAt||0)&&(!n.dayPath?.length||dist(n.dayPath.at(-1),dest)>(/^(escort-|story-task-)/.test(n.incidentOrder?.objective||'')?1:3))){pathBudget--;navigationCredits--;n.nextPathAt=sim.time+(/^(escort-|story-task-)/.test(n.incidentOrder?.objective||'')?.4:2);n.dayPath=findPath(n,dest,world.obstacles);}if(!n.dayPath?.length&&dist(n,dest)>.8)aim=n;if(n.dayPath?.length){if(dist(n,n.dayPath[0])<.2)n.dayPath.shift();aim=n.dayPath[0]||dest;}}n.speed=steer(n,aim,n.busYieldTarget?2.3:n.follow?4.6:n.sceneTarget?2.8:n.dayTarget?(n.incidentOrder?.speed??n.crowdSpeed??2.0):1.05,dt,world.obstacles);if(n.speed>.2)n.yaw=Math.atan2(n.x-ox,n.z-oz);if(n.livingActor&&n.dayTarget&&dist(n,n.dayTarget)<2&&day?.state.actors[n.id])day.state.actors[n.id].district=districtAt(n.x,n.z).id;}else n.speed=0;if(n.sceneTarget&&dist(n,n.sceneTarget)>.8){const remaining=dist(n,n.sceneTarget);if(n.sceneProgressDistance==null||remaining<n.sceneProgressDistance-.5){n.sceneProgressDistance=remaining;n.sceneStuckSeconds=0;}else n.sceneStuckSeconds=(n.sceneStuckSeconds||0)+dt;if(n.sceneStuckSeconds>=1.2){n.sceneStuckSeconds=0;n.sceneProgressDistance=remaining;n.dayPath=[];n.nextPathAt=0;const e=day?.encounter?.(n.scenePlan?.encounterId);if(e)prepareCast(e,day.location(e));}}else{n.sceneStuckSeconds=0;n.sceneProgressDistance=null;}n.model.position.set(n.x,0,n.z);n.model.rotation.y=n.yaw;if(n.ring){n.ring.position.set(n.x,.04,n.z);n.ring.visible=d<18;}}
for(const c of sim.police){c.model.position.set(c.x,0,c.z);c.model.rotation.y=c.yaw;if(c.state==='notice'&&c.seen>.2&&!c.noticeBubble){c.noticeBubble=true;say({name:'OFFICER',model:c.model},'One moment. What is going on here?',3);sound.sfx('whistle',{distance:dist(c,sim.player)});}if(c.state==='patrol')c.noticeBubble=false;}}
function syncPhysicalActors(){if(!day)return;const visible=npcs.filter(n=>n.livingActor&&!n.hidden);updateWorldPhysicalState(day.state,visible.map(n=>{const a=day.state.actors[n.id],actual=districtAt(n.x,n.z).id;return {id:n.id,district:actual,activity:n.incidentOrder?n.incidentOrder.objective:n.presentationIntent?.activity,arrived:!!n.dayTarget&&!n.incidentOrder&&!n.sceneTarget&&dist(n,n.dayTarget)<1.9&&n.speed<.25,suppliesPoint:dist(n,{x:-69,z:5})<3,nearbyActorIds:visible.filter(other=>other!==n&&dist(n,other)<3&&canReachInteraction(n,other,world.obstacles)).map(other=>other.id)};}));for(const n of visible)if(day.state.actors[n.id])day.state.actors[n.id].district=districtAt(n.x,n.z).id;}

