function storyBodies(){const t=day?.state.crisisTasks?.task;const held=new Set([...(taskProjection?.reservedActorIds||[]),...(t&&(['following','separated'].includes(t.status)||(t.status==='completed'&&(t.holdSeconds||0)<60))?[t.actorId]:[])]);return taskBodies().filter(b=>!held.has(b.id));}
function applyStoryResult(result){storyProjection=result;for(const e of result.events||[]){if(e.type==='story-task-completed'){applyCompletedStoryTaskEffects(day.state,e.id);if(e.kind==='mic'){sound.sfx('pickup');const ravi=npcs.find(n=>n.id==='ravi');if(ravi)say(ravi,'Hello? Haan! Peechhe waalon, ab aa rahi hai?',6);}}const actor=npcs.find(n=>n.id===e.actorIds?.[0]);if(actor&&e.type==='story-task-started')say(actor,'Saath chal. Google Maps ban ke aage mat nikal.',5);if(e.type==='story-task-completed')toast(e.kind==='mic'?'The microphone works. People turn to listen.':'You arrived together. This is now part of the day.',5);else if(e.type==='story-task-abandoned')toast('You stepped away. The task remains unfinished.',4);}applyStreetResult(result,'physical-task');}
