function crisisActions(){const labels={'keep-passage':'Side mein jagah hai — idhar aao!','rally':'Saath raho. Koi akela nahi.'};return (crisisProjection?.options||[]).filter(id=>id!=='leave').map(id=>({id:'crisis:'+id,type:'custom',label:labels[id],run:()=>{const result=actCrisis(day.state,incidentBodies(),id,{canSee:(a,b)=>visible(a,b,world.obstacles)});if(!result.ok){toast(result.reason);return;}crisisProjection=result;applyStreetResult(result,'crisis');checkpoint();}}));}
