function legacyDestinationActions(){return DESTINATIONS.filter(d=>dist(d.location,sim.player)<3.3&&canReachInteraction(sim.player,{...d.location,y:0},world.obstacles)).map(d=>({id:'visit:'+d.id,type:'custom',label:'Visit '+d.name,run:()=>dialogue('shop_'+d.id,d.setup,d.actions.map(a=>({label:a.label,action:()=>{const r=performDestination(game.destinations,d.id,a.id);if(!r.ok)return;sim.trust=Math.max(0,sim.trust+(r.effects.trust||0));sim.aura=Math.max(0,sim.aura+(r.effects.aura||0));sim.player.stamina=clamp(sim.player.stamina+(r.effects.stamina||0),0,100);if(day?.state.player)day.state.player.fatigue=clamp((day.state.player.fatigue||0)+(r.effects.fatigue||0),0,100);if(d.id==='kirana'&&a.id==='sort'&&!r.repeated)game.waterStock=6;say('shop_'+d.id,r.line,9);streetAudio.voice('shop_'+d.id,r.line,{distance:2});streetAudio.cue('rim');if(!r.repeated){memory(d.name,r.line);if(day)day.state.flags['neighbourhood_'+r.flag]=true;}checkpoint();}})),90)}));}
function openExplore(){if(transit?.aboard){toast('Choose a stop with the driver, then step out to explore.');return;}mode='explore';keys={};autoWalk=null;sound.pause(true);screen(`<div class="tiny">DELHI / TAKE THE LONG WAY</div><h2>WHERE TO?</h2><p>Walk to a nearby bus stop, visit the market, or find a quiet corner. These routes are on foot; boarding is your choice.</p><div class="lead-buttons">${(transit?.markers()||[]).map(b=>`<button data-trip="${b.id}">Bus: ${b.name}</button>`).join('')}${DESTINATIONS.map(d=>`<button data-place="${d.id}">${d.name}</button>`).join('')}</div><button id="closeExplore">Back to the street</button>`);const close=()=>{mode='play';$('#screen').classList.add('hidden');sound.pause(false);};$('#closeExplore').onclick=close;document.querySelectorAll('[data-trip]').forEach(b=>b.onclick=()=>{const bus=transit.state.buses.find(q=>q.id===b.dataset.trip);close();const stop=bus.route.points.filter(p=>p.stop).sort((a,b)=>dist(a,sim.player)-dist(b,sim.player))[0];if(bus.status==='stopped'&&dist(bus,stop)<1){walkTo(boardingApproach(bus));}else{walkTo({x:stop.x+3.2,z:stop.z+2.7,label:stop.name+' bus stop'});}toast('The stop panel shows the shuttle status. When it arrives, choose Walk to the open door.',6);});document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const d=DESTINATIONS.find(q=>q.id===b.dataset.place);close();walkTo({...d.location,label:d.name});});}
