 day=new DayClient({hasPendingTasks:()=>!!storyProjection?.objective,waitWorld:waitPhysicalWorld,mode:()=>mode,position:()=>sim.player,pause:()=>{streetAudio.stop();mode='day';keys={};autoWalk=null;sound.pause(true);},resume:prior=>{mode=['end','caught','pause'].includes(prior)?prior:'play';sound.pause(mode!=='play');keys={};},focus:p=>{cinemaTarget=p;},scene:reel=>{if(reel)dayPresentation.onScene({title:reel.title,location:reel.location,presentation:reel.cinematic});else{dayPresentation.scene=null;dayPresentation.stopNodes();for(const n of npcs){n.sceneTarget=null;n.scenePlan=null;n.sceneSpeaking=false;}}},releaseScene:()=>{document.body.classList.remove('performing');player.userData.sceneGesture=null;for(const n of npcs){n.sceneTarget=null;n.scenePlan=null;n.sceneSpeaking=false;n.sceneGesture=null;}},prepare:prepareCast,castReady:castReadiness,castDiagnostic:e=>castReadiness(e),stage:stageBeat,perform:(e,c,b)=>{const n=npcs.find(n=>n.id===b.speaker);if(n){say(n,b.line,7);n.sceneGesture=b.action;}if(/phone|ring|vibrat/.test(b.action||''))sound.sfx('pickup');},walk:dest=>{mode='play';const free=nearestFreePoint(dest,world.obstacles,{radius:.65,maxRadius:8});walkTo({...dest,...free});},toast,clearRoute:()=>{autoWalk=null;navTarget=null;},sting:()=>{},consequence:(result,choice,state)=>{const eff=result.appliedEffects||choice.effects||[];for(const e of eff){if(e.type==='escalation'&&e.value>0)sim.provoke(Math.min(35,e.value*4));if(e.type==='aid'&&e.value>0)sim.trust+=e.value; if(e.type==='credibility'&&e.value>0)sim.aura+=Math.ceil(e.value/2);}checkpoint();}});
